package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import android.location.Address;import org.json.*;
/** Local editor only. Selecting a point searches only after the user's search button. */
final class SavedNavigationRoutesDialog {
 interface Preview{void open(String id,int revision,int leg);}
 static void error(Activity a,Exception e){new AlertDialog.Builder(a).setMessage(e.getMessage()==null?"記録を確認できません":e.getMessage()).setPositiveButton("閉じる",null).show();}
 static void show(Activity host,Preview preview){try{JSONArray rows=SavedNavigationRoutes.list(host);AlertDialog[] top={null};LinearLayout body=new LinearLayout(host);body.setOrientation(1);TextView hint=new TextView(host);hint.setText("区間の順序と移動手段を保存します。利用する区間を現在時刻で検索し直します。最後の取得経路は、別の閲覧専用画面で確認できます。個人情報の同梱・初期登録はありません。");body.addView(hint);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);Button b=new Button(host);b.setText(SavedNavigationRoutes.summary(row));body.addView(b);b.setOnClickListener(v->{if(top[0]!=null)top[0].dismiss();new AlertDialog.Builder(host).setTitle(row.optString("name")).setItems(new String[]{"途中から再開・区間の候補を確認","編集","削除"},(d,which)->{try{if(which==0){JSONArray legs=row.getJSONArray("legs");String[] labels=new String[legs.length()];for(int k=0;k<labels.length;k++){JSONObject l=legs.getJSONObject(k);labels[k]=(k+1)+". "+SavedNavigationRoutes.label(l.optString("mode"))+"："+l.getJSONObject("from").optString("name")+" → "+l.getJSONObject("to").optString("name");}new AlertDialog.Builder(host).setTitle("開始する区間を選ぶ").setItems(labels,(a,k)->new AlertDialog.Builder(host).setTitle("この区間から候補を確認しますか？").setMessage(NavigationCommutePolicy.resumeNotice(k)+"\n地点情報を検索サービスへ送り、現在時刻で検索します。").setPositiveButton("候補を検索",(c,w)->preview.open(row.optString("id"),row.optInt("revision"),k)).setNegativeButton("戻る",null).show()).setNegativeButton("戻る",null).show();}else if(which==1)edit(host,row,preview);else new AlertDialog.Builder(host).setMessage("この個人設定のルートを削除しますか？ 現在の案内は変更しません。").setPositiveButton("削除",(a,k)->{try{SavedNavigationRoutes.remove(host,row.getString("id"),row.getInt("revision"));show(host,preview);}catch(Exception e){error(host,e);}}).setNegativeButton("戻る",null).show();}catch(Exception e){error(host,e);}}).setNegativeButton("閉じる",null).show();});}
 for(int kind=0;kind<3;kind++){final int k=kind;Button create=new Button(host);create.setText(kind==0?"新しく区間を組む":kind==1?"自転車→電車→バス→徒歩の下書き":"徒歩→電車→自転車の下書き");body.addView(create);create.setOnClickListener(v->{try{if(top[0]!=null)top[0].dismiss();JSONObject draft=k==0?new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("revision",0).put("name","").put("legs",new JSONArray().put(SavedNavigationRoutes.leg("","","walking"))):SavedNavigationRoutes.draft(k==1?"行き（下書き）":"帰り（下書き）",k==2);edit(host,draft,preview);}catch(Exception e){error(host,e);}});}
 ScrollView scroll=new ScrollView(host);scroll.addView(body);top[0]=new AlertDialog.Builder(host).setTitle("よく使うルート・区間指定").setView(scroll).setNegativeButton("閉じる",null).show();}catch(Exception e){error(host,e);}}
 static EditText input(Activity a,LinearLayout root,String hint,String value){EditText e=new EditText(a);e.setHint(hint);e.setText(value);root.addView(e);return e;}
 static void edit(Activity host,JSONObject original,Preview preview)throws Exception{JSONObject route=new JSONObject(original.toString());LinearLayout root=new LinearLayout(host);root.setOrientation(1);EditText name=input(host,root,"ルート名（例：行き／帰り）",route.optString("name"));Spinner shortcut=new Spinner(host);shortcut.setAdapter(new ArrayAdapter<String>(host,android.R.layout.simple_spinner_dropdown_item,new String[]{"ショートカットなし","行きとして呼び出す","帰りとして呼び出す"}));shortcut.setSelection(route.optString("shortcut").equals("outbound")?1:route.optString("shortcut").equals("return")?2:0);root.addView(shortcut);LinearLayout rows=new LinearLayout(host);rows.setOrientation(1);root.addView(rows);Runnable[] draw={null};draw[0]=()->{rows.removeAllViews();JSONArray legs=route.optJSONArray("legs");for(int i=0;i<legs.length();i++){final int index=i;JSONObject leg=legs.optJSONObject(i);Button b=new Button(host);b.setText((i+1)+". "+SavedNavigationRoutes.label(leg.optString("mode"))+" "+leg.optJSONObject("from").optString("name")+" → "+leg.optJSONObject("to").optString("name")+(SavedNavigationRoutes.ready(leg)?"":"（入力待ち）"));rows.addView(b);b.setOnClickListener(v->editLeg(host,route,index,draw[0]));if(i>0){Button up=new Button(host);up.setText("この区間を一つ上へ");rows.addView(up);up.setOnClickListener(v->{try{Object a=legs.get(index-1),c=legs.get(index);legs.put(index-1,c);legs.put(index,a);draw[0].run();}catch(Exception e){error(host,e);}});}}};draw[0].run();Button add=new Button(host);add.setText("区間を追加");root.addView(add);add.setOnClickListener(v->{try{JSONArray legs=route.getJSONArray("legs");if(legs.length()>=12)throw new Exception("区間は12件までです");JSONObject l=SavedNavigationRoutes.leg("","","walking");if(legs.length()>0)l.put("from",new JSONObject(legs.getJSONObject(legs.length()-1).getJSONObject("to").toString()));legs.put(l);draw[0].run();}catch(Exception e){error(host,e);}});ScrollView scroll=new ScrollView(host);scroll.addView(root);AlertDialog dialog=new AlertDialog.Builder(host).setTitle("よく使うルートを編集").setView(scroll).setPositiveButton("端末内に暗号化して保存",null).setNegativeButton("キャンセル",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{route.put("shortcut",new String[]{"none","outbound","return"}[shortcut.getSelectedItemPosition()]);route.put("name",name.getText().toString().trim());SavedNavigationRoutes.save(host,route);dialog.dismiss();show(host,preview);}catch(Exception e){error(host,e);}});}
 static void editLeg(Activity host,JSONObject route,int index,Runnable refresh){try{JSONObject leg=new JSONObject(route.getJSONArray("legs").getJSONObject(index).toString());LinearLayout root=new LinearLayout(host);root.setOrientation(1);String[] modes={"walking","bicycling","rail","bus"};Spinner mode=new Spinner(host);mode.setAdapter(new ArrayAdapter<String>(host,android.R.layout.simple_spinner_dropdown_item,new String[]{"徒歩","自転車","電車","バス"}));for(int i=0;i<modes.length;i++)if(modes[i].equals(leg.optString("mode")))mode.setSelection(i);root.addView(mode);
 for(String key:new String[]{"from","to"}){Button point=new Button(host);point.setText((key.equals("from")?"出発地点：":"到着地点：")+leg.getJSONObject(key).optString("name")+(SavedNavigationRoutes.located(leg.getJSONObject(key))?"":"（候補を選択）"));root.addView(point);point.setOnClickListener(v->NavigationEntranceDialog.showDestination(host,leg.optJSONObject(key).optString("name"),(label,address)->{try{leg.put(key,new JSONObject().put("name",label).put("latitude",address.getLatitude()).put("longitude",address.getLongitude()));point.setText((key.equals("from")?"出発地点：":"到着地点：")+label);}catch(Exception e){error(host,e);}}));}
 if(index>0){Button reuse=new Button(host);reuse.setText("前区間の到着地点を出発地に使う");root.addView(reuse);reuse.setOnClickListener(v->{try{JSONObject previous=route.getJSONArray("legs").getJSONObject(index-1).getJSONObject("to");if(!SavedNavigationRoutes.located(previous))throw new Exception("先に前区間の到着地点を候補から選んでください");leg.put("from",new JSONObject(previous.toString()));android.widget.Toast.makeText(host,"前区間の到着地点を使います："+previous.getString("name"),android.widget.Toast.LENGTH_LONG).show();}catch(Exception e){error(host,e);}});}
 Button linked=new Button(host);linked.setText(leg.optString("landmarkId").isEmpty()?"出口・駐輪メモを関連付ける":"関連メモを変更（未変更なら維持）");root.addView(linked);linked.setOnClickListener(v->{try{JSONArray notes=NavigationLandmarks.list(host);String[] labels=new String[notes.length()+1];labels[0]="関連付けを外す";for(int i=0;i<notes.length();i++)labels[i+1]=notes.getJSONObject(i).getString("name");new AlertDialog.Builder(host).setTitle("この区間で確認するメモ").setItems(labels,(d,k)->{try{if(k==0){leg.remove("landmarkId");linked.setText("関連付けなし");}else{JSONObject note=notes.getJSONObject(k-1);leg.put("landmarkId",note.getString("id"));linked.setText("関連メモ："+note.getString("name"));}}catch(Exception e){error(host,e);}}).setNegativeButton("戻る",null).show();}catch(Exception e){error(host,e);}});
 EditText board=input(host,root,"乗車駅・停留所（電車・バスで必須）",leg.optString("board")),alight=input(host,root,"降車駅・停留所（電車・バスで必須）",leg.optString("alight")),line=input(host,root,"路線名（指定する場合）",leg.optString("line")),entry=input(host,root,"入口・出口メモ（未確認なら空欄）",leg.optString("entry"));EditText parking=input(host,root,"駐輪の余裕（分・0〜60）",String.valueOf(leg.optInt("parkingMinutes",0))),gate=input(host,root,"改札の余裕（分・0〜60）",String.valueOf(leg.optInt("gateMinutes",0))),inside=input(host,root,"駅構内移動の余裕（分・0〜60）",String.valueOf(leg.optInt("stationMinutes",0)));for(EditText number:new EditText[]{parking,gate,inside})number.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);TextView note=new TextView(host);note.setText("入口は、地点候補の住所・座標と一致するか確認してください。交通機関は指定の乗降地点・路線に合う候補だけを出します。区間間の乗り換え・駐輪は自動完了しません。");root.addView(note);ScrollView scroll=new ScrollView(host);scroll.addView(root);AlertDialog dialog=new AlertDialog.Builder(host).setTitle("区間 "+(index+1)).setView(scroll).setPositiveButton("区間を反映",null).setNeutralButton("この区間を削除",(d,w)->{try{JSONArray before=route.getJSONArray("legs"),next=new JSONArray();for(int i=0;i<before.length();i++)if(i!=index)next.put(before.get(i));route.put("legs",next);refresh.run();}catch(Exception e){error(host,e);}}).setNegativeButton("戻る",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{leg.put("parkingMinutes",Integer.parseInt(parking.getText().toString())).put("gateMinutes",Integer.parseInt(gate.getText().toString())).put("stationMinutes",Integer.parseInt(inside.getText().toString()));NavigationCommutePolicy.validate(leg);leg.put("mode",modes[mode.getSelectedItemPosition()]).put("board",board.getText().toString().trim()).put("alight",alight.getText().toString().trim()).put("line",line.getText().toString().trim()).put("entry",entry.getText().toString().trim());route.getJSONArray("legs").put(index,leg);refresh.run();dialog.dismiss();}catch(Exception e){error(host,e);}});}catch(Exception e){error(host,e);}}
 static void shortcut(Activity host,String kind,Preview preview){try{JSONArray all=SavedNavigationRoutes.list(host),rows=new JSONArray();for(int i=0;i<all.length();i++)if(kind.equals(all.getJSONObject(i).optString("shortcut")))rows.put(all.get(i));if(rows.length()==0){new AlertDialog.Builder(host).setMessage("このショートカットの登録はありません。保存ルートの編集で「行き」「帰り」を選んで保存してください。初期登録はありません。").setPositiveButton("閉じる",null).show();return;}String[] names=new String[rows.length()];for(int i=0;i<names.length;i++)names[i]=rows.getJSONObject(i).getString("name");new AlertDialog.Builder(host).setTitle(kind.equals("return")?"帰りのルート":"行きのルート").setItems(names,(d,k)->{try{JSONObject row=rows.getJSONObject(k);JSONArray legs=row.getJSONArray("legs");String[] labels=new String[legs.length()];for(int i=0;i<labels.length;i++){JSONObject leg=legs.getJSONObject(i);labels[i]=(i+1)+". "+SavedNavigationRoutes.label(leg.getString("mode"))+" "+leg.getJSONObject("from").optString("name")+" → "+leg.getJSONObject("to").optString("name");}new AlertDialog.Builder(host).setTitle("開始区間を選ぶ").setItems(labels,(a,index)->new AlertDialog.Builder(host).setTitle("候補を検索しますか？").setMessage(NavigationCommutePolicy.resumeNotice(index)+"\n現在地と地点情報を検索サービスへ送り、候補を取り直します。開始は別に確認します。").setPositiveButton("候補を確認",(x,w)->preview.open(row.optString("id"),row.optInt("revision"),index)).setNegativeButton("戻る",null).show()).setNegativeButton("閉じる",null).show();}catch(Exception e){error(host,e);}}).setNegativeButton("閉じる",null).show();}catch(Exception e){error(host,e);}}
 private SavedNavigationRoutesDialog(){}
}
